func longestPalindrome(s string) string {
	n := len(s)
	if n < 2 {
		return s
	}
	maxLen, begin := 1, 0
	// dp[i][j] 表示 s[i..j] 是否是回文串
	dp := make([][]bool, n)
	for i := range dp {
		dp[i] = make([]bool, n)
		dp[i][i] = true
	}
	// 递推开始，先枚举子串长度
	for L := 2; L <= n; L++ {
		// 枚举左边界，左边界的上限设置可以宽松一些
		for i := 0; i < n; i++ {
			// 由 L 和 i 可以确定右边界，即 j - i + 1 = L
			j := L + i - 1
			// 如果右边界越界，就可以退出当前循环
			if j >= n {
				break
			}
			if s[i] != s[j] {
				dp[i][j] = false
			} else {
				if j-i < 3 {
					dp[i][j] = true
				} else {
					dp[i][j] = dp[i+1][j-1]
				}
			}
			// 只要 dp[i][j] 为 true，就表示子串 s[i..j] 是回文，此时记录回文长度和起始位置
			if dp[i][j] && j-i+1 > maxLen {
				maxLen = j - i + 1
				begin = i
			}
		}
	}
	return s[begin : begin+maxLen]
}
